    /** 替换/改单绑定的所属 Lane 准入事件。 */
    private com.surprising.aeron.service.order.admission.ReplacementAdmissionEvent replacementAdmission;''')
change('        return liquidation.check();','''        if (liquidationCheck == null)
            liquidationCheck = new com.surprising.aeron.service.liquidation.RuntimeDerivativeLiquidationProcessor.ExecutionCheck();
        return liquidationCheck;''')
change('return liquidation.reusableWork();','return reusableLiquidationWork;')
change('保存非空强平执行工作，具体检查交给强平上下文。','保存非空强平执行工作，后续命令复用同一工作对象。')
change('        liquidation.reusableWork(work);','        reusableLiquidationWork = Objects.requireNonNull(work);')
change('        replace.clear();','        replacementAdmission = null;',3)
change('        trigger.clear();','        triggerAdmissionOrder = null;\n        sourceTrigger = null;',2)
change('        liquidation.clear();','        clearLiquidationReferences();',2)
