change('return replace.admission();','return replacementAdmission;')
change('event == null || replace.admission != null','event == null || replacementAdmission != null')
change('        replace.admission(event);','        replacementAdmission = event;')
change('var value = replace.admission; replace.admission = null; return value;','var value = replacementAdmission; replacementAdmission = null; return value;')
change('return trigger.sourceTrigger();','return sourceTrigger;')
change('将非空源触发单首次绑定到专有上下文，重复绑定由上下文拒绝。','首次绑定非空源触发单收据，重复绑定立即拒绝。')
change('        trigger.sourceTrigger(value);','''        if (value == null || sourceTrigger != null) throw new IllegalStateException("trigger receipt already bound");
        sourceTrigger = value;''')
change('return trigger.admissionOrder();','return triggerAdmissionOrder;')
change('        trigger.admissionOrder(order);','        triggerAdmissionOrder = order;')
change('        deferred.set(clusterTimestamp, clusterPosition, sourceKey);','''        deferredClusterTimestamp = clusterTimestamp;
        deferredClusterPosition = clusterPosition;
        deferredSourceKey = sourceKey;''')
